"""Dependency-safe conditional prefix-tree column reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded optimizer for character-prefix reuse with conditional field trees."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional input reference and the last returned orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one cell using empty text for scalar missing values."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute an exact string LCP with binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Score a fixed string collection by sorted adjacent character LCPs."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        score = 0
        previous = ordered[0]
        for current in ordered[1:]:
            score += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return score

    @staticmethod
    def _dependency_edges(columns, requested, col_merge):
        """Build deduplicated precedence edges from dependencies and merge chains."""
        positions = {}
        for i, column in enumerate(columns):
            positions.setdefault(str(column), []).append(i)

        edges = []
        seen = set()

        def add_edge(left, right):
            """Add one valid directed edge if both names identify one column."""
            li = positions.get(str(left), [])
            ri = positions.get(str(right), [])
            if len(li) == 1 and len(ri) == 1 and li[0] != ri[0]:
                edge = (li[0], ri[0])
                if edge not in seen:
                    seen.add(edge)
                    edges.append(edge)

        for pair in requested or []:
            if isinstance(pair, (list, tuple)) and len(pair) >= 2:
                add_edge(pair[0], pair[1])

        for chain in col_merge or []:
            if isinstance(chain, (list, tuple)):
                values = list(chain)
            else:
                values = [chain]
            for left, right in zip(values, values[1:]):
                add_edge(left, right)

        return edges

    @classmethod
    def _constrained_order(cls, m, preference, columns, dependencies, col_merge):
        """Return a deterministic preference-ranked topological column order."""
        edges = cls._dependency_edges(columns, dependencies, col_merge)
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: i for i, column in enumerate(preference)}
        heap = [(rank[i], i) for i in range(m) if indegree[i] == 0]
        heapq.heapify(heap)
        result = []

        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank[nxt], nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _column_statistics(text):
        """Compute repetition and serialized-length statistics once per column."""
        n, m = text.shape
        result = []
        for col in range(m):
            counts = {}
            lengths = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
                lengths[value] = len(value)
            pairs = sum(
                lengths[value] * count * (count - 1)
                for value, count in counts.items()
            )
            total = sum(lengths[value] * count for value, count in counts.items())
            result.append((pairs, total))
        return result

    @staticmethod
    def _serialize_rows(text, orders):
        """Serialize each row according to its row-specific field permutation."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @classmethod
    def _conditional_tree(
        cls, text, base_order, stats, dependencies, col_merge
    ):
        """Construct bounded recursive conditional prefix partitions."""
        n, m = text.shape
        if n == 0 or m <= 1:
            return [list(base_order) for _ in range(n)]

        # Precompute integer factor codes and code lengths once per column.
        codes = np.empty((n, m), dtype=np.int32)
        code_lengths = []
        for col in range(m):
            mapping = {}
            values = []
            encoded = np.empty(n, dtype=np.int32)
            for row, value in enumerate(text[:, col]):
                code = mapping.get(value)
                if code is None:
                    code = len(values)
                    mapping[value] = code
                    values.append(value)
                encoded[row] = code
            codes[:, col] = encoded
            code_lengths.append(np.asarray([len(v) for v in values], dtype=np.int64))

        # Predecessor masks make availability checks cheap and deterministic.
        edges = cls._dependency_edges(
            list(range(m)), dependencies, col_merge
        )
        predecessors = [0] * m
        for left, right in edges:
            predecessors[right] |= 1 << left

        position = {col: i for i, col in enumerate(base_order)}
        orders = [None] * n
        nodes_used = [0]
        max_depth = min(m, 6)
        max_nodes = 128
        max_candidates = 24

        def tail(selected_mask):
            """Complete a partial path with a stable dependency-safe tail."""
            remaining = [c for c in base_order if not (selected_mask >> c) & 1]
            result = []
            done = selected_mask
            while remaining:
                choice = None
                for col in remaining:
                    if predecessors[col] & ~done == 0:
                        choice = col
                        break
                if choice is None:
                    # This is only reachable for cyclic malformed constraints.
                    result.extend(remaining)
                    break
                result.append(choice)
                done |= 1 << choice
                remaining.remove(choice)
            return result

        def visit(rows, selected_mask, path, depth):
            """Recursively split rows on the best available repeated field."""
            available = [
                col for col in base_order
                if not (selected_mask >> col) & 1
                and predecessors[col] & ~selected_mask == 0
            ]
            if (
                not rows
                or not available
                or depth >= max_depth
                or nodes_used[0] >= max_nodes
            ):
                final = path + tail(selected_mask)
                for row in rows:
                    orders[row] = final[:]
                return

            # Evaluate only the strongest deterministic candidate columns.
            available.sort(
                key=lambda col: (-stats[col][0], -stats[col][1], position[col])
            )
            chosen = None
            best_value = 0
            for col in available[:max_candidates]:
                local_codes = codes[rows, col]
                counts = np.bincount(local_codes)
                lengths = code_lengths[col]
                pair_value = int(
                    np.sum(lengths[: len(counts)] * counts * (counts - 1))
                )
                if pair_value > best_value:
                    best_value = pair_value
                    chosen = col

            if chosen is None or best_value <= 0:
                final = path + tail(selected_mask)
                for row in rows:
                    orders[row] = final[:]
                return

            groups = {}
            for row in rows:
                groups.setdefault(int(codes[row, chosen]), []).append(row)

            # Splitting must actually expose repeated-value groups.
            if len(groups) == 1:
                final = path + tail(selected_mask | (1 << chosen))
                final = path + [chosen] + tail(selected_mask | (1 << chosen))
                for row in rows:
                    orders[row] = final[:]
                return

            nodes_used[0] += 1
            next_mask = selected_mask | (1 << chosen)
            next_path = path + [chosen]
            for group_rows in groups.values():
                if nodes_used[0] >= max_nodes:
                    final = next_path + tail(next_mask)
                    for row in group_rows:
                        orders[row] = final[:]
                else:
                    visit(group_rows, next_mask, next_path, depth + 1)

        visit(list(range(n)), 0, [], 0)
        return orders

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort by serialized strings and copy only original cells."""
        n, m = source.shape
        row_order = sorted(range(n), key=lambda row: (serialized[row], row))
        output = np.empty((n, m), dtype=object)
        public_orders = []

        for out_row, source_row in enumerate(row_order):
            order = orders[source_row]
            output[out_row, :] = [source[source_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            output,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Compare one global order with one recursive conditional-tree order."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for col in range(m):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        stats = self._column_statistics(text)
        preference = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (-item[1][0], -item[1][1], item[0]),
            )
        ]
        global_order = self._constrained_order(
            m, preference, list(df.columns), one_way_dep, col_merge
        )

        candidates = [
            [global_order[:] for _ in range(n)],
            self._conditional_tree(
                text, global_order, stats, one_way_dep, col_merge
            ),
        ]

        best_orders = candidates[0]
        best_serialized = self._serialize_rows(text, best_orders)
        best_score = self._trie_score(best_serialized)

        tree_serialized = self._serialize_rows(text, candidates[1])
        tree_score = self._trie_score(tree_serialized)
        if tree_score > best_score:
            best_orders = candidates[1]
            best_serialized = tree_serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

